static string lower(string s){for(char &c:s) if(c>='A'&&c<='Z')c+=32;return s;}
static string trim(string s){size_t a=s.find_first_not_of(" \t"),b=s.find_last_not_of(" \t");return a==string::npos?"":s.substr(a,b-a+1);}
